/// [cleanup_resolve] approve; owner device or ticket only
nonisolated struct Flotilla_Pr_V1_CleanupResolveRequest: Sendable {
  // SwiftProtobuf.Message conformance is added in an extension below. See the
  // `Message` and `Message+*Additions` files in the SwiftProtobuf library for
  // methods supported on all messages.

  var jobID: String = String()

  var action: Flotilla_Pr_V1_CleanupResolveRequest.Action = .unspecified

  var unknownFields = SwiftProtobuf.UnknownStorage()

  nonisolated enum Action: SwiftProtobuf.Enum, Swift.CaseIterable {
    typealias RawValue = Int
    case unspecified // = 0

    /// remove a salvaged dirty tree anyway
    case remove // = 1
    case keep // = 2
    case UNRECOGNIZED(Int)

    init() {
      self = .unspecified
    }

    init?(rawValue: Int) {
      switch rawValue {
      case 0: self = .unspecified
      case 1: self = .remove
      case 2: self = .keep
      default: self = .UNRECOGNIZED(rawValue)
      }
    }

    var rawValue: Int {
      switch self {
      case .unspecified: return 0
      case .remove: return 1
      case .keep: return 2
      case .UNRECOGNIZED(let i): return i
      }
    }

    // The compiler won't synthesize support with the UNRECOGNIZED case.
    static let allCases: [Flotilla_Pr_V1_CleanupResolveRequest.Action] = [
      .unspecified,
      .remove,
      .keep,
    ]

  }

  init() {}
}

